// a shower of tiny bells for the particles
for (let i = 0; i < 46; i++) {
  const t = Math.pow(kit.random(), 1.8) * 1.1, f = 2000 + kit.random() * 7000;
  const o = ctx.createOscillator(); o.frequency.value = f;
  const g = ctx.createGain(); g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(0.08 + kit.random() * 0.1, t + 0.002); g.gain.setTargetAtTime(0, t + 0.004, 0.06 + kit.random() * 0.1);
  const p = ctx.createStereoPanner(); p.pan.value = kit.random() * 1.6 - 0.8;
  o.connect(g).connect(p).connect(ctx.destination); o.start(t); o.stop(t + 0.6);
}
